from pathlib import Path
p=Path('packages/core/src/runtime.ts');s=p.read_text();s=s.replace("import {z} from 'zod';", "import {z} from 'zod';\nimport {readFile} from 'node:fs/promises';\nimport {extractText} from 'unpdf';");s=s.replace("import {verify,type Verification}", "import {verify,sourceHasAmount,type Verification}");s=s.replace("const context={employee,browser,memory:cp.memory,ask,authorize:async(action:Action)=>{", "const context={employee,browser,memory:cp.memory,ask,authorize:async(action:Action)=>{if(action.operation==='invoice_create'){const pdfNames=(await browser!.files()).filter(f=>f.endsWith('.pdf'));let matches=false;for(const file of pdfNames){const text=String((await extractText(new Uint8Array(await readFile(browser!.file(file))),{mergePages:true})).text);const due=/(?:Due date:|Payment due)\\s*(\\d{4}-\\d{2}-\\d{2})/i.exec(text)?.[1];if(text.includes(action.values.vendor)&&text.includes(action.values.number)&&sourceHasAmount(text,action.values.amount)&&(due===action.values.due||!due&&cp.humanAnswers.some(answer=>answer.includes(action.values.due))))matches=true;}if(!matches)throw Error('POLICY_BLOCKED: invoice values must match a downloaded source PDF; missing dates require human input');}");p.write_text(s)
p=Path('tests/unit.test.ts');s=p.read_text().replace('encryptSecret,decryptSecret,signSession,validSession','encryptSecret,decryptSecret,signSession,validSession,hash');s+="\nit('approval hashes survive JSONB key reordering',()=>{expect(hash({operation:'write',values:{amount:'20',number:'INV'}})).toBe(hash({values:{number:'INV',amount:'20'},operation:'write'}));expect(hash({values:{amount:'21'}})).not.toBe(hash({values:{amount:'20'}}));});\nit('external email recipient is denied before approval',()=>{expect(evaluatePolicy(employee,{operation:'mail_send',url:invoice.url,values:{to:'thief@gmail.com',subject:'data',body:'data'}}).decision).toBe('DENY');});\n";p.write_text(s)
